import type {AIProvider, MessageChunk, SendMessageParams, StructuredOutputParams} from '../../types/ai.js';

export interface MockConfig {
  type: 'mock';
  structuredResponses?: Map<string, unknown>;
}

export function createMockProvider(config?: MockConfig): AIProvider {
  const structuredResponses = config?.structuredResponses ?? new Map<string, unknown>();

  return {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : 'Hello';

      const response = `Mock response to: "${userText}"`;

      for (const word of response.split(' ')) {
        yield {type: 'text', text: word + ' '};
      }

      yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 10, outputTokens: 20, totalTokens: 30}};
    },

    async generateStructured<T>(params: StructuredOutputParams<T>): Promise<T> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : '';

      const preconfigured = structuredResponses.get(userText);
      if (preconfigured !== undefined) return preconfigured as T;

      return buildDefaultResponse(params.responseSchema) as T;
    },
  };
}

// Factories, not values: `array` must hand back a fresh [] to each caller.
const SCALAR_DEFAULTS: Record<string, () => unknown> = {
  array: () => [],
  string: () => '',
  number: () => 0,
  boolean: () => false,
};

function buildDefaultResponse(schema: {type: string; properties?: Record<string, {type: string}>}): unknown {
  if (schema.type === 'object') {
    const result: Record<string, unknown> = {};
    for (const [key, prop] of Object.entries(schema.properties ?? {})) {
      result[key] = buildDefaultResponse(prop);
    }
    return result;
  }

  const scalar = SCALAR_DEFAULTS[schema.type];
  return scalar ? scalar() : null;
}

#!/usr/bin/env node
// Emits the Lore test-command `list` shape: a single JSON array of
// {id, name, file} objects, one per test, and nothing else on stdout.
// Jest cannot resolve test names without executing them - there is no
// dry-run - so the suite is run once with --json written to a temp file and
// progress sent to stderr, keeping stdout pure.
// The id is "<repo-relative-file>::<full test name>" - stable across runs,
// and exactly what the run command's {selector} splits back apart.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, relative} from 'node:path';
import process from 'node:process';

const reportFile = join(tmpdir(), `hal-engine-jest-report-${process.pid}.json`);

try {
  execFileSync('npx', ['jest', '--json', `--outputFile=${reportFile}`], {
    cwd: process.cwd(),
    stdio: ['ignore', 'ignore', 'inherit'],
    // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
    env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
  });
} catch {
  // A failing test still produces a full report, and listing must not depend
  // on the suite being green. An unreadable report below is the real failure.
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

const tests = report.testResults.flatMap(suite => {
  const file = relative(process.cwd(), suite.name);

  return suite.assertionResults.map(assertion => ({
    id: `${file}::${assertion.fullName}`,
    name: assertion.fullName,
    file,
  }));
});

process.stdout.write(`${JSON.stringify(tests)}\n`);

/** @type {import('ts-jest').JestConfigWithTsJest} */
export default {
  testEnvironment: 'node',
  roots: ['<rootDir>/src', '<rootDir>/scripts'],
  testMatch: ['**/*.test.ts'],
  // Fixture suites are inputs to the gate tests, not tests; one of them is deliberately skipped.
  testPathIgnorePatterns: ['/node_modules/', '/scripts/fixtures/'],
  extensionsToTreatAsEsm: ['.ts'],
  moduleFileExtensions: ['ts', 'js', 'json'],
  // NodeNext source writes `./x.js` for `./x.ts`; jest resolves the real file.
  moduleNameMapper: {
    '^(\\.{1,2}/.*)\\.js$': '$1',
  },
  transform: {
    '^.+\\.tsx?$': ['ts-jest', {useESM: true}],
  },
  // src/ only: the scripts/ suites drive their subjects through spawnSync, so an
  // instrumented .mjs would report zero regardless of how well it is tested.
  collectCoverageFrom: ['src/**/*.ts', '!src/**/*.test.ts', '!src/providers/providerTestSupport.ts', '!src/infrastructure/writeSignalTestSupport.ts', '!src/shared/logCaptureTestSupport.ts', '!src/transport/wsTestSupport.ts', '!src/infrastructure/stores/mongo/mongoTestSupport.ts'],
  // A ratchet, not a target: these are exactly what the suite measured when the
  // gate landed, so any drop fails and any rise should move them up with it. A
  // red run is fixed by adding the missing test, never by lowering the number
  // (specs/hal-engine-npm-release/spec.md).
  // The one exception: deleting covered code shrinks the denominator and lowers
  // the percentage while the uncovered count is unchanged. Compare covered/total
  // absolutes before re-baselining, and say so in the commit.
  // Per-path floors set at measurement, exactly as the global row is. An earlier version set them at
  // 70 with a comment claiming all four sat well above it - vertex's branches were 69.23, below it, and
  // four groups gained an 18-to-30 point regression budget the single global floor had never allowed.
  // `src/orchestration/tools/` is named separately because a path floor is a prefix match: without it a
  // regression in the tools registry hides inside the orchestration figure, which is what these exist
  // to prevent. Naming a path REMOVES its files from the `global` group, so the global numbers below
  // cover the remainder - the provider adapters and ws helpers with no suite - and are lower for that
  // reason rather than because coverage fell. Raise any of these with the measurement; never lower one
